'use strict';
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={opportunities:[],favorites:[],runs:[]},view='all',currentJob=null,busy=false;
function localDay(){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Berlin'}).format(new Date())}
function age(r){return r.date?Math.floor((Date.parse(localDay()+'T00:00:00Z')-Date.parse(r.date+'T00:00:00Z'))/86400000):null}
const safeUrl=s=>{try{const u=new URL(s);return u.protocol==='https:'&&!u.username&&!u.password?u.href:null}catch{return null}};
async function api(path,body){const res=await fetch(path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json','X-Hunter-Token':state.token},body:body===undefined?undefined:JSON.stringify(body)});let data;try{data=await res.json()}catch{throw Error('Réponse serveur illisible. Vérifiez que le serveur The Hunter est démarré.')}if(!res.ok)throw Error(data.error||'Erreur serveur');return data}
function toast(message,error=false){const el=$('toast');el.textContent=message;el.style.display='block';el.style.background=error?'#773344':'#33313b';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',6500)}
function modal(content){if(!$('detail').open)$('detail').showModal();$('detail').innerHTML='<button class="close" id="close">Fermer ×</button>'+content;$('close').onclick=()=>$('detail').close();$('detail').scrollTop=0}
async function refresh(){const previous=state.runs.length?$('runFilter').value:'';state=await api('/api/state');$('runFilter').innerHTML='<option value="all">Toutes les recherches</option>'+state.runs.slice().reverse().map(r=>`<option value="${esc(r.id)}">${esc(new Date(r.date).toLocaleString('fr-FR'))} · ${r.added} pistes</option>`).join('');$('runFilter').value=previous&&[...$('runFilter').options].some(o=>o.value===previous)?previous:(state.runs.at(-1)?.id||'all');render();updateConnection()}
function updateConnection(){$('connection').textContent=state.aiConfigured?(state.master?'Serveur connecté · prêt':'CV de référence manquant'):'Mode accompagné · sans clé API';$('sourceHint').textContent=$('sources').value==='all'?'75 sources prévues. Chaque recherche indique les sources réellement consultées.':$('sources').value+' : la prochaine recherche ciblera cette source.'}
function criteriaMatch(r){return r.openConfirmed&&r.match>=Number($('match').value)&&(!r.verified?!$('verified').checked:age(r)>=0&&age(r)<Number($('period').value))&&($('sector').value==='all'||r.sector===$('sector').value)&&(!$('remote').checked||r.compatible)&&($('sources').value==='all'||r.source.toLowerCase().includes($('sources').value.toLowerCase()))}
function runRows(){const run=state.runs.find(r=>r.id===$('runFilter').value);const urls=run?new Set((run.sourcesChecked||[]).map(s=>s.url)):null;return state.opportunities.filter(r=>!urls||urls.has(r.url))}
function filtered(){return runRows().filter(r=>view==='all'?true:view==='saved'?state.favorites.includes(r.id):view==='latent'?r.status==='latent':view==='rejected'?r.status!=='latent'&&!criteriaMatch(r):r.status!=='latent'&&criteriaMatch(r)).filter(r=>(r.company+' '+r.role).toLowerCase().includes($('search').value.toLowerCase())).sort((a,b)=>$('sort').value==='date'?(b.date||'').localeCompare(a.date||''):b[$('sort').value]-a[$('sort').value])}
function render(){let rows=filtered();const selected=runRows().filter(r=>r.status!=='latent'&&criteriaMatch(r));const scored=selected.filter(r=>r.matchStatus!=='not_scored');$('matchVal').textContent=$('match').value+' %';$('count').textContent=selected.length;$('allCount').textContent=runRows().length;$('navCount').textContent=state.opportunities.length;$('total').textContent=selected.length;$('average').textContent=scored.length?Math.round(scored.reduce((s,r)=>s+r.match,0)/scored.length)+' %':'—';$('hidden').textContent=selected.filter(r=>/niveau [23]|ats|portfolio/i.test(r.source)).length;$('saved').textContent=state.favorites.length;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('cards').innerHTML=rows.length?rows.map(r=>`<article class="card"><div class="card-top"><div class="logo">${esc(r.company.split(' ').map(s=>s[0]).join('').slice(0,3))}</div><div><div class="company">${esc(r.company)}</div><h3>${esc(r.role)}</h3></div><div class="match">${r.matchStatus==='not_scored'?'—':r.match+'%'}<small>correspondance CV</small></div></div><div class="chips"><span class="chip ${criteriaMatch(r)?'green':''}">${r.status==='latent'?'Signal latent':criteriaMatch(r)?'Retenue':'Écartée / à vérifier'}</span><span class="chip">${esc(r.sector)}</span><span class="chip">${esc(r.location)}</span><span class="chip green">${r.status==='latent'?'Signal à qualifier':r.verified?'Publié le '+esc(r.date):'Date non vérifiée'}</span></div><p>${esc((view==='rejected'||view==='all')?(r.reason||r.text.slice(0,260)):r.text.slice(0,260))}</p><div class="card-bottom"><span>${esc(r.source)} · ${r.matchStatus==='not_scored'?'Non scoré':'Score '+r.score+'/100'}</span><button class="details" data-id="${esc(r.id)}">Voir le poste & mon CV ↗</button></div></article>`).join(''):`<div class="empty"><h3>${state.opportunities.length?'Aucun résultat pour ces critères.':'Votre recherche commence ici.'}</h3><p>${state.opportunities.length?'Ajustez les filtres ou consultez les offres écartées.':(state.master?'Votre CV maître est prêt. Configurez la connexion IA puis lancez une recherche, ou ajoutez une offre.':'Importez votre CV de référence dans Paramètres, puis lancez une recherche.')}</p><button class="btn primary" id="emptySetup">${state.master?'Ajouter une offre':'Configurer mon espace'}</button></div>`;document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>openDetail(b.dataset.id));if($('emptySetup'))$('emptySetup').onclick=state.master?addJob:settings;const last=state.runs.at(-1);$('runSummary').innerHTML=last?`Dernière recherche : ${esc(new Date(last.date).toLocaleString('fr-FR'))} · ${last.added} nouvelles pistes. <button class="reset" id="history">Voir les sources consultées</button>`:'Aucune recherche effectuée. Les exemples fictifs ont été retirés.';if($('history'))$('history').onclick=history}
function settings(){modal(`<div class="eyebrow">MON ESPACE</div><h2>CV de référence & connexions</h2><div class="question"><label>1. Moteur OpenAI</label><p>${state.aiConfigured?'Clé configurée côté serveur.':'Clé manquante.'}</p><small>Renseignez OPENAI_API_KEY dans le fichier .env du projet. La clé reste côté serveur et n’est jamais renvoyée au navigateur. Les opérations IA envoient à OpenAI le CV et les éléments nécessaires à la demande.</small></div><div class="question"><label>2. CV maître</label><p>${state.master?esc(state.master.name):'Aucun CV importé.'}</p><p>Choisissez uniquement le CV de référence. Tout remplacement invalide les analyses précédentes.</p><input id="masterFile" type="file" accept=".pdf,.docx,.txt"><button class="btn primary" id="uploadMaster">Importer comme CV de référence</button><small>PDF avec texte, DOCX ou TXT · 8 Mo max. Mise en page d’export standard, non identique au fichier source.</small></div><div class="question"><label>3. Google Drive</label><p>${state.driveConfigured?'OAuth serveur configuré. La sauvegarde sera vérifiée lors de l’envoi.':'Connexion serveur à configurer.'}</p><small>La connexion Drive de ce chat ne peut pas être réutilisée par le serveur local. Renseignez les paramètres OAuth Google dans .env. Sans connexion, les CV restent téléchargeables en Word et PDF.</small></div><button class="btn" id="checkConfig">Actualiser les connexions</button>`);$('checkConfig').onclick=async()=>{await guard(refresh);settings()};$('uploadMaster').onclick=()=>guard(async()=>{const f=$('masterFile').files[0];if(!f)throw Error('Choisissez votre CV de référence.');if(f.size>8e6)throw Error('8 Mo maximum.');let raw=new Uint8Array(await f.arrayBuffer()),binary='';for(let i=0;i<raw.length;i+=8192)binary+=String.fromCharCode(...raw.subarray(i,i+8192));await api('/api/master',{name:f.name,data:btoa(binary)});await refresh();settings();toast('CV de référence importé.')})}
async function guard(fn){try{await fn()}catch(e){toast(e.message,true)}}
async function operation(path,payload,onDone){if(busy)return toast('Une opération est déjà en cours.',true);busy=true;$('run').disabled=true;$('activity').hidden=false;$('activity').textContent='Traitement en cours. Vous pouvez continuer à consulter les résultats.';try{const {taskId}=await api(path,payload);let result;while(true){await new Promise(r=>setTimeout(r,1800));result=await api('/api/task/'+taskId);if(result.status!=='running')break}if(result.status!=='succeeded')throw Error(result.error||'Opération interrompue');await refresh();if(onDone)await onDone(result.result);toast('Opération terminée.')}catch(e){toast(e.message,true)}finally{busy=false;$('run').disabled=false;$('activity').hidden=true}}
function searchJobs(){if(!state.aiConfigured||!state.master)return settings();operation('/api/search',{match:Number($('match').value),period:Number($('period').value),source:$('sources').value},()=>{view='selected';render();history()})}
function history(){const runs=state.runs.slice().reverse();modal('<div class="eyebrow">JOURNAL DES RECHERCHES</div><h2>Sources réellement consultées</h2>'+(!runs.length?'<p>Aucune recherche effectuée.</p>':runs.map(r=>`<div class="question"><label>${esc(new Date(r.date).toLocaleString('fr-FR'))} · ${r.added} pistes ajoutées</label><p>${esc(r.summary)}</p>${(r.sourcesChecked||[]).map(s=>`<p>${safeUrl(s.url)?`<a href="${esc(safeUrl(s.url))}" target="_blank" rel="noopener noreferrer">${esc(s.name)}</a>`:esc(s.name)} · ${esc(s.outcome)}</p>`).join('')}${(r.warnings||[]).map(w=>`<small>${esc(w)}</small>`).join('')}<h3>Actions prioritaires</h3><ul>${(r.actions||[]).map(a=>`<li>${esc(a)}</li>`).join('')}</ul></div>`).join('')))}
function addJob(){modal(`<div class="eyebrow">AJOUTER UNE OFFRE</div><h2>Analyser un poste précis</h2><form id="jobForm"><div class="question"><label for="company">Entreprise</label><input id="company" required><label for="role">Poste</label><input id="role" required><label for="url">Page originale</label><input id="url" type="url" placeholder="https://…" required><label for="jd">Description complète du poste</label><textarea id="jd" required minlength="100" rows="8"></textarea><label for="jobDate">Date de publication (si connue)</label><input id="jobDate" type="date"><label for="jobLocation">Localisation / politique remote</label><input id="jobLocation" required><label for="jobSource">Source</label><input id="jobSource" required><label for="jobSector">Secteur</label><select id="jobSector"><option>Web3 / Blockchain</option><option>FinTech</option><option>SaaS / AI</option><option>Telco</option></select><label class="check"><input id="jobOpen" type="checkbox"> J’ai confirmé que l’offre est ouverte</label><label class="check"><input id="jobCompatible" type="checkbox"> Localisation compatible</label><label class="check"><input id="jobVerified" type="checkbox"> Date vérifiée sur la page originale</label></div><p>Les vérifications manuelles sont enregistrées comme déclarées par vous. Le match sera calculé après analyse du CV.</p><button class="btn primary">Enregistrer & analyser</button></form>`);$('jobForm').onsubmit=e=>{e.preventDefault();guard(async()=>{let row={company:$('company').value,role:$('role').value,url:$('url').value,text:$('jd').value,date:$('jobDate').value,location:$('jobLocation').value,source:$('jobSource').value,sector:$('jobSector').value,openConfirmed:$('jobOpen').checked,compatible:$('jobCompatible').checked,verified:$('jobVerified').checked,match:0,score:0,status:'selected'};await api('/api/import',{rows:[row]});await refresh();let job=state.opportunities.find(r=>r.url===row.url);await openDetail(job.id);})}}
async function openDetail(id){currentJob=id;const r=state.opportunities.find(r=>r.id===id);if(!r)return;modal(`<div class="eyebrow">${esc(r.company)}</div><h2>${esc(r.role)}</h2><div class="chips"><span class="chip">${esc(r.location)}</span><span class="chip green">${r.matchStatus==='not_scored'?'Match non calculé':'Match '+r.match+'%'}</span><span class="chip">${r.verification==='user'?'Vérifications déclarées':'Vérifications web'}</span></div><p><a href="${esc(safeUrl(r.url))}" target="_blank" rel="noopener noreferrer">Ouvrir la page originale ↗</a></p><details><summary>Description complète</summary><p style="white-space:pre-wrap">${esc(r.text)}</p></details>${r.reason?`<p>${esc(r.reason)}</p>`:''}<p>Publication : ${esc(r.date||'inconnue')} · ${r.openConfirmed?'Statut ouvert confirmé':'Statut à vérifier'}</p><p>${esc(r.angle)}</p><p>${esc(r.contact)}</p><div id="cvArea"><p>Chargement de votre dossier…</p></div><p><button class="btn" id="favorite">${state.favorites.includes(id)?'Retirer de ma sélection':'☆ Ajouter à ma sélection'}</button></p>`);$('favorite').onclick=()=>guard(async()=>{state.favorites=await api('/api/favorites',{ids:state.favorites.includes(id)?state.favorites.filter(v=>v!==id):[...state.favorites,id]});render();$('favorite').textContent=state.favorites.includes(id)?'Retirer de ma sélection':'☆ Ajouter à ma sélection'});await guard(async()=>{const dossier=await api('/api/job/'+id);if(currentJob===id&&$('cvArea'))renderDossier(r,dossier)})}
function renderDossier(r,dossier){const a=dossier.analysis;const stale=a&&(a.masterHash!==state.master?.hash);let g=dossier.generated;const answers=dossier.answers||{};if(stale)g=null;const area=$('cvArea');area.innerHTML=`${g?generatedHTML(g):''}<div class="steps"><span class="on">01 · Analyse</span><span>→</span><span>02 · Vos réponses</span><span>→</span><span>03 · Mon CV adapté</span></div>${!a||stale?`<div class="notice">${stale?'Le CV maître a changé. Refaites l’analyse.':'Analysez les exigences du poste par rapport au CV de référence pour obtenir les questions ciblées.'}</div><p><button class="btn primary" id="analyze">Analyser & adapter mon CV →</button></p>`:`<p>${esc(a.summary)}</p><details><summary>Mots-clés et preuves (${a.keywords.length})</summary><div style="overflow:auto"><table><thead><tr><th>Mot-clé</th><th>Couverture</th><th>Preuve</th></tr></thead><tbody>${a.keywords.map(k=>`<tr><td>${esc(k.keyword)}</td><td>${esc(k.coverage)}</td><td>${esc(k.evidence)}</td></tr>`).join('')}</tbody></table></div></details><p>Écarts : ${(a.gaps||[]).map(esc).join(' · ')||'Aucun écart signalé par l’analyse.'}</p><h3>${a.questions.length?'Vos précisions':'Aucune question nécessaire'}</h3><form id="answerForm">${a.questions.map(q=>`<div class="question"><label for="${q.id}">${esc(q.question)}</label><textarea id="${q.id}">${esc(answers[q.id]?.text||'')}</textarea><label class="check"><input type="checkbox" id="confirm_${q.id}" ${answers[q.id]?.state==='confirmed'?'checked':''}> Je confirme cette expérience</label><label class="check"><input type="checkbox" id="skip_${q.id}" ${answers[q.id]?.state==='skip'?'checked':''}> Non couvert / ne pas intégrer</label></div>`).join('')}<div class="flow-footer"><button type="button" class="btn" id="saveAnswers">Enregistrer mes réponses</button><button class="btn primary" type="submit">Générer mon CV →</button></div></form><p><button class="reset" id="reanalyze">Refaire l’analyse</button></p>`}`;
const analyzeAction=()=>state.aiConfigured?operation('/api/analyze',{id:r.id},()=>openDetail(r.id)):prepareCVRequest(r.id,'analyze');if($('analyze'))$('analyze').onclick=analyzeAction;if($('reanalyze'))$('reanalyze').onclick=analyzeAction;
if($('answerForm')){const collect=()=>{const result={};for(const q of a.questions){const confirm=$('confirm_'+q.id).checked,skip=$('skip_'+q.id).checked;if(confirm&&skip)throw Error('Choisissez confirmer OU ne pas intégrer.');result[q.id]={text:$(q.id).value,state:skip?'skip':confirm?'confirmed':'pending'}}return result};$('saveAnswers').onclick=()=>guard(async()=>{await api('/api/answers',{id:r.id,answers:collect()});toast('Réponses sauvegardées.');if($('generatedCV'))$('generatedCV').remove()});$('answerForm').onsubmit=e=>{e.preventDefault();guard(async()=>{await api('/api/answers',{id:r.id,answers:collect()});state.aiConfigured?operation('/api/generate',{id:r.id},()=>openDetail(r.id)):prepareCVRequest(r.id,'generate')})}}
if(!state.aiConfigured){if($('analyze'))$('analyze').textContent='Préparer l’adaptation dans le chat →';const submit=$('answerForm')?.querySelector('[type=submit]');if(submit)submit.textContent='Continuer la rédaction dans le chat →';const message=document.createElement('p');message.className='notice';message.textContent='Mode sans clé : vos réponses sont sauvegardées ici. L’analyse et la rédaction se poursuivent dans notre chat après envoi de la demande ; le clic ne lance pas de génération automatique.';area.prepend(message)}if(dossier.cvRequest&&!g)renderCVRequest(dossier.cvRequest);
if($('saveDrive'))$('saveDrive').onclick=()=>operation('/api/drive',{id:r.id},()=>openDetail(r.id));}
async function prepareCVRequest(id,stage){await guard(async()=>{const request=await api('/api/cv-request',{id,stage});renderCVRequest(request);toast('Demande préparée. Copiez-la dans notre chat pour continuer.')})}
function renderCVRequest(request){let panel=$('chatHandoff');if(!panel){panel=document.createElement('section');panel.id='chatHandoff';$('cvArea').append(panel)}panel.className='question';panel.innerHTML=`<h3>Continuer ici, dans notre chat</h3><p>Demande enregistrée. Elle ne sera pas envoyée automatiquement au chat.</p><label for="chatPrompt">1. Copiez cette demande</label><textarea id="chatPrompt" readonly rows="6">${esc(request.prompt)}</textarea><button class="btn primary" id="copyCVPrompt">Copier la demande</button><p>2. Collez-la dans cette conversation, puis envoyez-la. L’analyse, les questions et le CV seront traités ici.</p><small>La demande n’inclut ni clé API, ni contenu du CV maître.</small>`;$('copyCVPrompt').onclick=async()=>{try{await navigator.clipboard.writeText(request.prompt);$('copyCVPrompt').textContent='Copié ✓ · collez dans le chat'}catch{$('chatPrompt').focus();$('chatPrompt').select();toast('Sélectionnez le texte puis copiez-le avec Cmd+C.')} };panel.scrollIntoView({behavior:'smooth',block:'nearest'})}

function generatedHTML(g){return `<section id="generatedCV"><h2>${g.draft?'Votre CV adapté · brouillon':'Votre CV adapté'}</h2>${g.draftNote?`<div class="notice">${esc(g.draftNote)}</div>`:''}<div class="chips"><span class="chip">Avant : ${g.matchBefore}%</span><span class="chip green">Après : ${g.matchAfter}% · ${g.generationMode==='chat'?'estimation métier':'estimation IA'}</span></div><div class="cv-sheet"><h1>${esc(g.name)}</h1><p><b>${esc(g.headline)}</b></p><p>${esc(g.contact)}</p>${g.sections.map(s=>`<h3>${esc(s.title)}</h3>${s.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}`).join('')}</div><p>Écarts restants : ${(g.gaps||[]).map(esc).join(' · ')||'Aucun signalé.'}</p><p>${esc(g.layoutNote)}</p><div class="actions"><a class="btn primary" href="/download/${g.id}.docx" download="${esc(g.filename)}.docx">Télécharger Word</a><a class="btn" href="/download/${g.id}.pdf" download="${esc(g.filename)}.pdf">Télécharger PDF</a><a class="btn" href="/download/${g.id}.pdf?preview=1" target="_blank" rel="noopener noreferrer">Ouvrir le PDF ↗</a><button class="btn" id="saveDrive">Sauvegarder dans Drive</button></div>${Object.entries(g.driveLinks||{}).map(([ext,url])=>safeUrl(url)?`<p><a href="${esc(url)}" target="_blank" rel="noopener noreferrer">Ouvrir le ${esc(ext)} dans Drive ↗</a></p>`:'').join('')}</section>`}
function downloadCSV(){const fields=['company','role','url','match','score','date','sector','location','source','compatible','verified','openConfirmed','status','reason','text','matchStatus'];let text=[fields.join(','),...filtered().map(r=>fields.map(k=>'"'+String(r[k]??'').replace(/"/g,'""')+'"').join(','))].join('\r\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/csv;charset=utf-8'}));a.download='The Hunter Log - '+localDay()+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function parseCSV(s){let rows=[],row=[],v='',q=false;s=s.replace(/^\ufeff/,'');for(let i=0;i<s.length;i++){let c=s[i];if(c==='"'){if(q&&s[i+1]==='"'){v+='"';i++}else q=!q}else if(c===','&&!q){row.push(v);v=''}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&s[i+1]==='\n')i++;row.push(v);if(row.some(Boolean))rows.push(row);row=[];v=''}else v+=c}if(q)throw Error('CSV : guillemets non fermés');row.push(v);if(row.some(Boolean))rows.push(row);return rows}
$('import').onclick=()=>$('file').click();$('file').onchange=e=>guard(async()=>{const f=e.target.files[0];if(!f)return;const rows=parseCSV(await f.text()),headers=rows.shift();const result=rows.map(row=>{const r=Object.fromEntries(headers.map((k,i)=>[k,row[i]||'']));for(let k of ['verified','compatible','openConfirmed'])r[k]=r[k]==='true';return r});await api('/api/import',{rows:result});await refresh();toast('Résultats importés.');e.target.value=''});
$('runFilter').onchange=render;$('export').onclick=downloadCSV;$('settings').onclick=settings;$('run').onclick=searchJobs;$('addJob').onclick=addJob;$('flowSources').onclick=()=>{$('sources').scrollIntoView({behavior:'smooth',block:'center'});$('sources').focus()};$('flowMatch').onclick=()=>{$('match').scrollIntoView({behavior:'smooth',block:'center'});$('match').focus()};function firstCV(){const r=filtered().find(r=>r.status!=='latent');if(r)openDetail(r.id);else toast('Ajoutez ou recherchez une offre pour adapter votre CV.',true)}$('flowQuestions').onclick=firstCV;$('flowCV').onclick=firstCV;
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});for(let id of ['match','period','sector','remote','verified','search','sort','sources'])$(id).addEventListener('input',()=>{render();updateConnection();try{localStorage.setItem('hunter-filters',JSON.stringify(Object.fromEntries(['match','period','sector','remote','verified','sources'].map(id=>[id,$(id).type==='checkbox'?$(id).checked:$(id).value]))))}catch{}});
$('reset').onclick=()=>{$('match').value=70;$('period').value=5;$('sector').value='all';$('sources').value='all';$('remote').checked=true;$('verified').checked=true;$('search').value='';render();updateConnection()};
try{const prefs=JSON.parse(localStorage.getItem('hunter-filters')||'{}');for(let [k,v] of Object.entries(prefs)){if(!['match','period','sector','remote','verified','sources'].includes(k))continue;if($(k).type==='checkbox')$(k).checked=v;else $(k).value=v}}catch{}
refresh().catch(e=>{toast(e.message,true);$('cards').innerHTML='<div class="empty">Serveur indisponible. Démarrez le serveur The Hunter avec start.command.</div>'});
